/**
 * Platform-specific installation information for the Antigravity CLI companion
 * tool.
 */
export interface AntigravityInstallInfo {
  /** Human-readable name of the detected platform. */
  platformName: string;
  /** The command the user should run to install the Antigravity CLI. */
  installCmd: string;
}

/**
 * Returns platform-specific installation information for the Antigravity CLI.
 *
 * Detection is based on `process.platform`. On Windows we further distinguish
 * between PowerShell and Command Prompt using the presence of the
 * `PSModulePath` environment variable.
 *
 * @param platform The platform identifier (defaults to `process.platform`).
 * @param env The environment variables (defaults to `process.env`).
 * @returns The install info, or `null` for unsupported platforms.
 */
export function getAntigravityInstallInfo(
  platform: NodeJS.Platform = process.platform,
  env: NodeJS.ProcessEnv = process.env,
): AntigravityInstallInfo | null {
  switch (platform) {
    case 'darwin':
      return {
        platformName: 'macOS',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.sh | bash',
      };
    case 'linux':
      return {
        platformName: 'Linux',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.sh | bash',
      };
    case 'win32':
      if (env['PSModulePath']) {
        return {
          platformName: 'Windows (PowerShell)',
          installCmd: 'irm https://antigravity.google/cli/install.ps1 | iex',
        };
      }
      return {
        platformName: 'Windows (Command Prompt)',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.cmd -o install.cmd && install.cmd && del install.cmd',
      };
    default:
      return null;
  }
}
